      vrfId: varchar("vrf_id").references(() => ipamVrfs.id, { onDelete: "restrict" }),
      status: text("status").notNull().default("available").$type(),
      assignedDeviceId: varchar("assigned_device_id").references(() => devices.id, { onDelete: "set null" }),
      assignedInterfaceId: varchar("assigned_interface_id").references(() => deviceInterfaces.id, { onDelete: "set null" }),
      // FK to specific interface
      assignedInterfaceIndex: integer("assigned_interface_index"),
