    pingHistory = pgTable("ping_history", {
      id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
      targetId: varchar("target_id").notNull().references(() => pingTargets.id, { onDelete: "cascade" }),
      timestamp: timestamp("timestamp", { withTimezone: true }).defaultNow().notNull(),
      // Packet statistics
      sent: integer("sent").notNull(),
      // Packets sent
      received: integer("received").notNull(),
      // Packets received
      lossPct: doublePrecision("loss_pct").notNull(),
      // Loss percentage (0-100)
      // RTT statistics in milliseconds (all as double for precision)
      rttMin: doublePrecision("rtt_min"),
      // Minimum RTT
      rttMax: doublePrecision("rtt_max"),
      // Maximum RTT
      rttAvg: doublePrecision("rtt_avg"),
      // Average RTT
      rttMdev: doublePrecision("rtt_mdev"),
      // Standard deviation
      // Percentiles for smokeping-style visualization
      rttP10: doublePrecision("rtt_p10"),
      // 10th percentile
      rttP25: doublePrecision("rtt_p25"),
      // 25th percentile
      rttP50: doublePrecision("rtt_p50"),
      // Median (50th percentile)
      rttP75: doublePrecision("rtt_p75"),
      // 75th percentile
      rttP90: doublePrecision("rtt_p90"),
      // 90th percentile
      rttP95: doublePrecision("rtt_p95")
      // 95th percentile
    }, (table) => [
      index("idx_ping_history_target_time").on(table.targetId, table.timestamp),
      index("idx_ping_history_timestamp").on(table.timestamp)
    ]);
