async function testConnection(config) {
  const testPool = new Pool2({
    host: config.host,
    port: config.port,
    database: config.database,
    user: config.username,
    password: config.password,
    ssl: config.ssl ? { rejectUnauthorized: false } : false,
    max: 1,
    connectionTimeoutMillis: 1e4
  });
  try {
    const client2 = await testPool.connect();
    try {
      await client2.query("SELECT 1");
      const extResult = await client2.query(
        "SELECT EXISTS(SELECT 1 FROM pg_extension WHERE extname = 'timescaledb') as has_timescale"
      );
      const hasTimescale = extResult.rows[0]?.has_timescale === true;
      if (hasTimescale) {
        return {
          success: true,
          message: "Connection successful. TimescaleDB extension detected.",
          hasTimescaleExtension: true
        };
      }
      const dbResult = await client2.query("SELECT current_database() as db");
      const dbName = dbResult.rows[0]?.db || config.database;
      const availableResult = await client2.query(
        "SELECT 1 FROM pg_available_extensions WHERE name = 'timescaledb'"
      ).catch(() => ({ rows: [] }));
      const isAvailable = availableResult.rows.length > 0;
      return {
        success: true,
        message: isAvailable ? `Connection successful, but TimescaleDB extension is not enabled on database "${dbName}". Connect as a superuser (e.g. postgres) and run:
\\c ${dbName}
CREATE EXTENSION IF NOT EXISTS timescaledb;` : `Connection successful, but TimescaleDB extension is NOT installed on this server. Please install it first.`,
        hasTimescaleExtension: false
      };
    } finally {
      client2.release();
    }
  } catch (error) {
    return {
      success: false,
      message: `Connection failed: ${error.message}`,
      hasTimescaleExtension: false
    };
  } finally {
    await testPool.end().catch(() => {
    });
  }
}
async function initializeHypertables(pool2, retentionDays) {
  const client2 = await pool2.connect();
  const createdTables = [];
  try {
    const extResult = await client2.query(
      "SELECT EXISTS(SELECT 1 FROM pg_extension WHERE extname = 'timescaledb') as has_timescale"
    );
    if (!extResult.rows[0]?.has_timescale) {
      try {
        await client2.query("CREATE EXTENSION IF NOT EXISTS timescaledb");
        console.log("[TimescaleDB] Created timescaledb extension");
      } catch (e) {
        const dbResult = await client2.query("SELECT current_database() as db, current_user as usr");
        const dbName = dbResult.rows[0]?.db || "your_database";
        const dbUser = dbResult.rows[0]?.usr || "corebit";
        const availableResult = await client2.query(
          "SELECT 1 FROM pg_available_extensions WHERE name = 'timescaledb'"
        ).catch(() => ({ rows: [] }));
        const isAvailable = availableResult.rows.length > 0;
        if (isAvailable) {
          return {
            success: false,
            message: `TimescaleDB is installed on the server but not enabled on database "${dbName}". The user "${dbUser}" lacks permission to create extensions.

Connect as a superuser (e.g. postgres) and run:

\\c ${dbName}
CREATE EXTENSION IF NOT EXISTS timescaledb;

Then retry initialization in CoreBit.`,
            tables: []
          };
        }
        return {
          success: false,
          message: `TimescaleDB extension is not available on this PostgreSQL server: ${e.message}.

Please install TimescaleDB on the target server first. See: https://docs.timescale.com/install/`,
          tables: []
        };
      }
    }
    const userResult = await client2.query("SELECT current_user as usr");
    const currentUser = userResult.rows[0]?.usr;
    try {
      await client2.query(`GRANT CREATE ON SCHEMA public TO "${currentUser}"`);
    } catch (grantErr) {
      const privCheck = await client2.query(
        "SELECT has_schema_privilege(current_user, 'public', 'CREATE') as can_create"
      );
      if (!privCheck.rows[0]?.can_create) {
        return {
          success: false,
          message: `Permission denied: The database user "${currentUser}" cannot create tables in the public schema. This is common on PostgreSQL 15+. A superuser or database owner must run:

GRANT CREATE ON SCHEMA public TO "${currentUser}";

Then retry initialization.`,
          tables: []
        };
      }
    }
    for (const schema of HYPERTABLE_SCHEMAS) {
      const tableExists = await client2.query(
        "SELECT EXISTS(SELECT 1 FROM information_schema.tables WHERE table_name = $1) as exists",
        [schema.name]
      );
      if (!tableExists.rows[0]?.exists) {
        await client2.query(schema.create);
        console.log(`[TimescaleDB] Created table ${schema.name}`);
      } else {
        const constraintResult = await client2.query(
          `SELECT tc.constraint_name, tc.constraint_type
           FROM information_schema.table_constraints tc
           JOIN information_schema.key_column_usage kcu
             ON tc.constraint_name = kcu.constraint_name AND tc.table_name = kcu.table_name
           WHERE tc.table_name = $1
             AND tc.constraint_type IN ('PRIMARY KEY', 'UNIQUE')
           GROUP BY tc.constraint_name, tc.constraint_type
           HAVING COUNT(*) = 1 AND MAX(kcu.column_name) = 'id'`,
          [schema.name]
        );
        for (const row of constraintResult.rows) {
          await client2.query(`ALTER TABLE ${schema.name} DROP CONSTRAINT "${row.constraint_name}"`);
          console.log(`[TimescaleDB] Dropped ${row.constraint_type} constraint "${row.constraint_name}" from ${schema.name} (incompatible with hypertable partitioning)`);
        }
        const idxResult = await client2.query(
          `SELECT i.relname as index_name
           FROM pg_index ix
           JOIN pg_class t ON t.oid = ix.indrelid
           JOIN pg_class i ON i.oid = ix.indexrelid
           JOIN pg_attribute a ON a.attrelid = t.oid AND a.attnum = ANY(ix.indkey)
           WHERE t.relname = $1 AND ix.indisunique = true AND array_length(ix.indkey, 1) = 1 AND a.attname = 'id'
             AND NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conindid = i.oid)`,
          [schema.name]
        );
        for (const row of idxResult.rows) {
          await client2.query(`DROP INDEX IF EXISTS "${row.index_name}"`);
          console.log(`[TimescaleDB] Dropped unique index "${row.index_name}" on ${schema.name}.id (incompatible with hypertable partitioning)`);
        }
      }
      if (schema.name === "ping_history") {
        for (const col of ["device_id", "ip_address"]) {
          try {
            const colInfo = await client2.query(
              `SELECT is_nullable FROM information_schema.columns WHERE table_name = 'ping_history' AND column_name = $1`,
              [col]
            );
            if (colInfo.rows.length > 0 && colInfo.rows[0].is_nullable === "NO") {
              await client2.query(`ALTER TABLE ping_history ALTER COLUMN ${col} DROP NOT NULL`);
              console.log(`[TimescaleDB] Made ping_history.${col} nullable for compatibility`);
            }
          } catch (e) {
            console.warn(`[TimescaleDB] Could not alter ping_history.${col}:`, e.message);
          }
        }
        for (const col of ["rtt_p10", "rtt_p25", "rtt_p50", "rtt_p75", "rtt_p90", "rtt_p95"]) {
          try {
            const exists = await client2.query(
              `SELECT 1 FROM information_schema.columns WHERE table_name = 'ping_history' AND column_name = $1`,
              [col]
            );
            if (exists.rows.length === 0) {
              await client2.query(`ALTER TABLE ping_history ADD COLUMN ${col} DOUBLE PRECISION`);
              console.log(`[TimescaleDB] Added percentile column ping_history.${col}`);
            }
          } catch (e) {
            console.warn(`[TimescaleDB] Could not add ping_history.${col}:`, e.message);
          }
        }
      }
      const isHypertable = await client2.query(
        "SELECT EXISTS(SELECT 1 FROM timescaledb_information.hypertables WHERE hypertable_name = $1) as is_hypertable",
        [schema.name]
      );
      if (!isHypertable.rows[0]?.is_hypertable) {
        await client2.query(
          `SELECT create_hypertable('${schema.name}', '${schema.timeColumn}', migrate_data => true, if_not_exists => true)`
        );
        console.log(`[TimescaleDB] Converted ${schema.name} to hypertable`);
      }
      const indexName = `idx_ts_${schema.name.replace(/_history$/, "")}_time`;
      if (schema.name === "device_metrics_history") {
        await client2.query(`CREATE INDEX IF NOT EXISTS ${indexName} ON ${schema.name} (device_id, "timestamp" DESC)`);
      } else if (schema.name === "connection_bandwidth_history") {
        await client2.query(`CREATE INDEX IF NOT EXISTS ${indexName} ON ${schema.name} (connection_id, "timestamp" DESC)`);
      } else if (schema.name === "prometheus_metrics_history") {
        await client2.query(`CREATE INDEX IF NOT EXISTS ${indexName} ON ${schema.name} (device_id, metric_id, "timestamp" DESC)`);
      } else if (schema.name === "ping_history") {
        await client2.query(`CREATE INDEX IF NOT EXISTS ${indexName} ON ${schema.name} (target_id, "timestamp" DESC)`);
      }
      createdTables.push(schema.name);
    }
    await setupRetentionPolicies(client2, retentionDays);
    return {
      success: true,
      message: `Successfully initialized ${createdTables.length} hypertables with ${retentionDays}-day retention.`,
      tables: createdTables
    };
  } catch (error) {
    let message = `Initialization failed: ${error.message}`;
    if (error.message?.includes("permission denied") || error.message?.includes("Permission denied")) {
      const userRes = await client2.query("SELECT current_user as usr").catch(() => ({ rows: [{ usr: "unknown" }] }));
      const user = userRes.rows[0]?.usr || "your_user";
      message += `

A superuser must run: GRANT CREATE ON SCHEMA public TO "${user}";`;
    }
    return {
      success: false,
      message,
      tables: createdTables
    };
  } finally {
    client2.release();
  }
}
async function setupRetentionPolicies(client2, retentionDays) {
  const interval = `${retentionDays} days`;
  for (const schema of HYPERTABLE_SCHEMAS) {
    try {
      await client2.query(
        `SELECT remove_retention_policy('${schema.name}', if_exists => true)`
      );
      await client2.query(
        `SELECT add_retention_policy('${schema.name}', INTERVAL '${interval}', if_not_exists => true)`
      );
      console.log(`[TimescaleDB] Set retention policy for ${schema.name}: ${interval}`);
    } catch (e) {
      console.warn(`[TimescaleDB] Could not set retention policy for ${schema.name}: ${e.message}`);
    }
  }
}
async function updateRetentionDays(retentionDays) {
  if (!tsPool || !currentConfig) return;
  const client2 = await tsPool.connect();
  try {
    await setupRetentionPolicies(client2, retentionDays);
    if (currentConfig) {
      currentConfig.retentionDays = retentionDays;
    }
  } finally {
    client2.release();
  }
}
async function getTimescaleStats() {
  if (!tsPool || !currentConfig) return null;
  try {
    const client2 = await tsPool.connect();
    try {
      const tables = [];
      for (const schema of HYPERTABLE_SCHEMAS) {
        try {
          const countResult = await client2.query(`SELECT COUNT(*)::int as total_rows FROM ${schema.name}`);
          const rangeResult = await client2.query(
            `SELECT MIN("timestamp")::text as oldest, MAX("timestamp")::text as newest FROM ${schema.name}`
          );
          const sizeResult = await client2.query(
            `SELECT pg_size_pretty(hypertable_size('${schema.name}')) as disk_size`
          );
          tables.push({
            name: schema.name,
            totalRows: countResult.rows[0]?.total_rows ?? 0,
            diskSize: sizeResult.rows[0]?.disk_size ?? "0 bytes",
            oldestTimestamp: rangeResult.rows[0]?.oldest ?? null,
            newestTimestamp: rangeResult.rows[0]?.newest ?? null
          });
        } catch {
          tables.push({ name: schema.name, totalRows: 0, diskSize: "N/A", oldestTimestamp: null, newestTimestamp: null });
        }
      }
      return {
        connected: true,
        tables,
        retentionDays: currentConfig.retentionDays
      };
    } finally {
      client2.release();
    }
  } catch {
    return { connected: false, tables: [], retentionDays: currentConfig?.retentionDays ?? 365 };
  }
}
