async function pingDevice(ipAddress, timeoutSeconds = 3) {
  return new Promise((resolve) => {
    if (!isIP(ipAddress)) {
      resolve({ success: false });
      return;
    }
    const isWindows = process.platform === "win32";
    const pingPath = isWindows ? "ping" : "/bin/ping";
    const pingArgs = isWindows ? ["-n", "1", "-w", String(timeoutSeconds * 1e3), ipAddress] : ["-c", "1", "-W", String(timeoutSeconds), ipAddress];
    execFile(pingPath, pingArgs, { timeout: (timeoutSeconds + 1) * 1e3 }, (error, stdout, stderr) => {
      if (error) {
        resolve({ success: false });
        return;
      }
      const rttMatch = stdout.match(/time[=<](\d+(?:\.\d+)?)\s*ms/i);
      const rtt = rttMatch ? parseFloat(rttMatch[1]) : void 0;
      resolve({ success: true, rtt });
    });
  });
}

