function recordProbeCycle(lane, durationMs, outcomes) {
  const seconds = durationMs / 1e3;
  probeCycleDuration.observe({ lane }, seconds);
  probeLastDuration.set({ lane }, seconds);
  probeCyclesTotal.inc({ lane });
  if (outcomes.success) probeDevicesTotal.inc({ lane, outcome: "success" }, outcomes.success);
  if (outcomes.timeout) probeDevicesTotal.inc({ lane, outcome: "timeout" }, outcomes.timeout);
  if (outcomes.error) probeDevicesTotal.inc({ lane, outcome: "error" }, outcomes.error);
  if (outcomes.skipped) probeDevicesTotal.inc({ lane, outcome: "skipped" }, outcomes.skipped);
}
