    // ===== API KEYS =====
    "/api/api-keys": {
      get: {
        tags: ["API Keys"],
        summary: "List all API keys",
        description: "Returns all API keys (without the actual key hash). Admin access required.",
        responses: { 200: { description: "Array of API keys", content: { "application/json": { schema: { type: "array", items: { $ref: "#/components/schemas/ApiKey" } } } } } }
      },
      post: {
        tags: ["API Keys"],
        summary: "Create API key",
        description: "Creates a new API key. The raw key is returned only once in the response.",
        requestBody: {
          required: true,
          content: {
            "application/json": {
              schema: {
                type: "object",
                properties: {
                  name: { type: "string", description: "Descriptive name for the key" },
                  accessLevel: { type: "string", enum: ["read", "readwrite", "admin"], description: "Access level: read (query only), readwrite (query + modify), admin (full access)" },
                  expiresAt: { type: "string", format: "date-time", description: "Optional expiration date" }
                },
                required: ["name", "accessLevel"]
              }
            }
          }
        },
        responses: {
          200: {
            description: "Created API key with raw key (shown only once)",
            content: {
              "application/json": {
                schema: {
                  allOf: [{ $ref: "#/components/schemas/ApiKey" }, { type: "object", properties: { rawKey: { type: "string", description: "The actual API key - save this, it won't be shown again" } } }]
                }
              }
            }
          }
        }
      }
    },
    "/api/api-keys/{id}": {
      patch: {
        tags: ["API Keys"],
        summary: "Update API key",
        description: "Update API key properties (name, access level, active status).",
        parameters: [{ name: "id", in: "path", required: true, schema: { type: "string" } }],
        requestBody: {
          required: true,
          content: { "application/json": { schema: { type: "object", properties: { name: { type: "string" }, accessLevel: { type: "string", enum: ["read", "readwrite", "admin"] }, active: { type: "boolean" } } } } }
        },
        responses: { 200: { description: "Updated API key" }, 404: { description: "API key not found" } }
      },
      delete: {
        tags: ["API Keys"],
        summary: "Delete API key",
        parameters: [{ name: "id", in: "path", required: true, schema: { type: "string" } }],
        responses: { 200: { description: "API key deleted" } }
      }
    },
