  app2.post(
    "/api/alarm-mutes",
    requireSuperuserOrAdmin,
    async (req, res) => {
      try {
        const { userId, duration, reason } = req.body;
        let muteUntil = null;
        if (duration && duration !== "forever") {
          const hours = parseInt(duration);
          if (!isNaN(hours)) {
            muteUntil = new Date(Date.now() + hours * 60 * 60 * 1e3);
          }
        }
        const mute = await storage.createAlarmMute({
          userId: userId || null,
          // null = global mute
          mutedBy: req.user.id,
          muteUntil,
          reason: reason || null
        });
        const mutedUser = mute.userId ? await storage.getUser(mute.userId) : null;
        const mutedByUser = await storage.getUser(mute.mutedBy);
        res.json({
          ...mute,
          mutedUser: mutedUser ? {
            id: mutedUser.id,
            username: mutedUser.username,
            displayName: mutedUser.displayName
          } : null,
          mutedByUser: mutedByUser ? {
            id: mutedByUser.id,
            username: mutedByUser.username,
            displayName: mutedByUser.displayName
          } : null
        });
      } catch (error) {
        console.error("Error creating alarm mute:", error);
        res.status(500).json({ error: "Failed to create alarm mute" });
      }
    }
  );
