  app2.post("/api/device-groups/:id/test", canModify, async (req, res) => {
    try {
      const g = await storage.getDeviceGroup(req.params.id);
      if (!g) return res.status(404).json({ error: "Group not found" });
      const mockDevice = {
        id: "test",
        name: `Test (${g.name})`,
        ipAddress: "0.0.0.0",
        type: "test",
        status: "online"
      };
      const notifIds = await storage.getNotificationsForGroup(g.id);
      let channelsFired = 0;
      for (const id of notifIds) {
        const n = await storage.getNotification(id);
        if (n) {
          await sendNotification(n, mockDevice, "online", "offline");
          channelsFired++;
        }
      }
      const onDuty = await storage.getCurrentlyOnDutyUsersForGroup(g.id);
      let userChannelsFired = 0;
      for (const u of onDuty) {
        const chs = await storage.getUserNotificationChannels(u.id);
        for (const ch of chs) {
          if (!ch.enabled) continue;
          await sendUserNotification(ch, mockDevice, "online", "offline", u.displayName || u.username);
          userChannelsFired++;
        }
      }
      res.json({
        success: true,
        group: g.name,
        channelsFired,
        userChannelsFired,
        onDutyUsers: onDuty.length
      });
    } catch (e) {
      console.error("device-groups test error:", e?.message);
      res.status(500).json({ error: "Failed to test-fire", details: e?.message });
    }
  });
