  app2.post("/api/plugins/install", requireAdmin, async (req, res) => {
    try {
      const contentType = req.headers["content-type"] || "";
      if (!contentType.includes("multipart/form-data")) {
        return res.status(400).json({ error: "Expected multipart/form-data" });
      }
      let file;
      try {
        file = await parseMultipart(req, 50 * 1024 * 1024);
      } catch (parseErr) {
        if (parseErr.message === "LIMIT_FILE_SIZE") {
          return res.status(400).json({ error: "File too large. Maximum 50 MB." });
        }
        return res.status(400).json({ error: parseErr.message || "Upload failed" });
      }
      if (!file.filename.toLowerCase().endsWith(".zip")) {
        return res.status(400).json({ error: "Only .zip plugin packages are accepted" });
      }
      const { createRequire: createRequire2 } = await import("module");
      const _require = createRequire2(import.meta.url);
      const AdmZip = _require("adm-zip");
      let zip;
      try {
        zip = new AdmZip(file.buffer);
      } catch {
        return res.status(400).json({ error: "Invalid or corrupted zip file" });
      }
      const entries = zip.getEntries();
      let rootDir = "";
      let manifestEntry = null;
      let indexEntry = null;
      for (const entry of entries) {
        const name = entry.entryName.replace(/\\/g, "/");
        if (name === "plugin.json") {
          manifestEntry = entry;
          rootDir = "";
        } else if (!manifestEntry && /^[^/]+\/plugin\.json$/.test(name)) {
          manifestEntry = entry;
          rootDir = name.split("/")[0] + "/";
        }
      }
      for (const entry of entries) {
        const name = entry.entryName.replace(/\\/g, "/");
        if (name === rootDir + "index.js") {
          indexEntry = entry;
          break;
        }
      }
      if (!manifestEntry) return res.status(400).json({ error: "plugin.json not found in zip" });
      if (!indexEntry) return res.status(400).json({ error: "index.js not found in zip" });
      let manifest;
      try {
        manifest = JSON.parse(zip.readAsText(manifestEntry));
      } catch {
        return res.status(400).json({ error: "Invalid plugin.json \u2014 must be valid JSON" });
      }
      if (!manifest.type || typeof manifest.type !== "string") {
        return res.status(400).json({ error: "plugin.json must include a 'type' string field" });
      }
      if (!manifest.name || typeof manifest.name !== "string") {
        return res.status(400).json({ error: "plugin.json must include a 'name' string field" });
      }
      const safeType = manifest.type.replace(/[^a-zA-Z0-9_-]/g, "_");
      const pluginBaseDir = getPluginDir();
      const pluginPath = path3.join(pluginBaseDir, safeType);
      if (!fs3.existsSync(pluginBaseDir)) {
        fs3.mkdirSync(pluginBaseDir, { recursive: true });
      }
      if (fs3.existsSync(pluginPath)) {
        fs3.rmSync(pluginPath, { recursive: true, force: true });
      }
      fs3.mkdirSync(pluginPath, { recursive: true });
      for (const entry of entries) {
        if (entry.isDirectory) continue;
        const name = entry.entryName.replace(/\\/g, "/");
        const relPath = rootDir ? name.startsWith(rootDir) ? name.slice(rootDir.length) : null : name;
        if (!relPath || relPath.includes("..") || relPath.startsWith("/")) continue;
        const destPath = path3.join(pluginPath, relPath);
        const destDir = path3.dirname(destPath);
        if (!fs3.existsSync(destDir)) fs3.mkdirSync(destDir, { recursive: true });
        fs3.writeFileSync(destPath, entry.getData());
      }
      fs3.writeFileSync(
        path3.join(pluginPath, "plugin.json"),
        JSON.stringify(manifest, null, 2),
        "utf-8"
      );
      await storage.createLog({
        eventType: "plugin_installed",
        severity: "info",
        message: `Plugin installed: ${manifest.name} v${manifest.version ?? "?"} (type=${manifest.type})`
      });
      res.json({
        type: manifest.type,
        name: manifest.name,
        version: manifest.version ?? "0.0.0",
        description: manifest.description,
        author: manifest.author
      });
    } catch (error) {
      console.error("[Plugin] Install error:", error);
      res.status(500).json({ error: "Plugin installation failed", details: error.message });
    }
  });
