  app2.get("/api/mib-cache/debug/:vendorId", requireAuth, async (req, res) => {
    try {
      await mibCache2.initialize();
      const vendorId = req.params.vendorId;
      const mibs = await mibCache2.getMibsForVendor(vendorId);
      const oidsByDepth = {};
      const sampleOids = [];
      let totalOids = 0;
      let resolvedOids = 0;
      let unresolvedOids = 0;
      for (const mib of mibs) {
        for (const [name, def] of Array.from(mib.oids)) {
          totalOids++;
          if (def.oid) {
            resolvedOids++;
            const depth = def.oid.split(".").length;
            oidsByDepth[depth] = (oidsByDepth[depth] || 0) + 1;
            if (def.oid.startsWith("1.3.6.1.4.1.") && sampleOids.length < 20) {
              sampleOids.push({
                oid: def.oid,
                name: def.name,
                depth,
                mibFile: mib.name
              });
            }
          } else {
            unresolvedOids++;
          }
        }
      }
      const depthDistribution = Object.entries(oidsByDepth).map(([depth, count2]) => ({ depth: parseInt(depth), count: count2 })).sort((a, b) => a.depth - b.depth);
      res.json({
        vendorId,
        mibFileCount: mibs.length,
        mibFiles: mibs.map((m) => m.name),
        totalOids,
        resolvedOids,
        unresolvedOids,
        depthDistribution,
        sampleEnterpriseOids: sampleOids.sort((a, b) => a.depth - b.depth)
      });
    } catch (error) {
      console.error("Error getting MIB debug info:", error);
      res.status(500).json({ error: "Failed to get MIB debug info", message: error.message });
    }
  });
