  async function getDeviceCustomMetricVariables(device) {
    const vars = [];
    const metricsConfigs = [];
    const customCreds = device.customCredentials;
    if (customCreds?.snmpMetrics && Array.isArray(customCreds.snmpMetrics)) {
      for (const metric of customCreds.snmpMetrics) {
        metricsConfigs.push({ id: metric.id, label: metric.label, unit: metric.unit });
      }
    }
    if (customCreds?.prometheusMetrics && Array.isArray(customCreds.prometheusMetrics)) {
      for (const metric of customCreds.prometheusMetrics) {
        metricsConfigs.push({ id: metric.id, label: metric.label, unit: metric.unit });
      }
    }
    if (device.credentialProfileId) {
      const profile = await storage.getCredentialProfile(device.credentialProfileId);
      if (profile) {
        const profileCreds = profile.credentials;
        if (profileCreds?.snmpMetrics && Array.isArray(profileCreds.snmpMetrics)) {
          for (const metric of profileCreds.snmpMetrics) {
            if (!metricsConfigs.find((m) => m.id === metric.id)) {
              metricsConfigs.push({ id: metric.id, label: metric.label, unit: metric.unit });
            }
          }
        }
        if (profileCreds?.prometheusMetrics && Array.isArray(profileCreds.prometheusMetrics)) {
          for (const metric of profileCreds.prometheusMetrics) {
            if (!metricsConfigs.find((m) => m.id === metric.id)) {
              metricsConfigs.push({ id: metric.id, label: metric.label, unit: metric.unit });
            }
          }
        }
      }
    }
    for (const metricConfig of metricsConfigs) {
      vars.push({
        id: `device.metric.${metricConfig.id}`,
        name: metricConfig.label,
        description: `Custom metric "${metricConfig.label}"`,
        namespace: "device",
        group: "Custom Metrics",
        unit: metricConfig.unit,
        format: "number"
      });
    }
    return vars;
  }
